// === Tab: mySketch ===
let font
let bug

function preload() {
  // Inter 600
  font = loadFont('file:///Users/unclerm/Vibe Coding/4K MV Visual Integration Editor/assets_cache/default_texture.png')
}

function setup() {
  createCanvas(600, 600, WEBGL)

  bug = buildGeometry(() => {
    fill(100)
    // Head
    push();
    translate(-50, 0, 0);
    sphere(70);
    for (let side of [-1, 1]) {
      fill(0)
      // Eye
      push();
      translate(-20, -60, side * 30);
      sphere(20);
      pop();

      // Antenna
      push();
      translate(0, -100, side * 30);
      rotateX(PI * -0.1 * side);
      cylinder(5, 100);
      pop();
    }
    pop();

    fill('#f24e4e')

    // Body
    push();
    translate(50, 0, 0);
    scale(1.5, 0.8, 1);
    sphere(100);
    pop();
  });
}

function draw() {
  const t = frameCount / 60 * 1000
  const scene = floor(t / 3000) % 5
  textFont(font)

  if (scene === 0) {
    background('#4287f5')
    noStroke()

    push()
    translate(-250, -250)
    textAlign(LEFT, TOP)
    textSize(50)
    text('beginContour()', 0, 0)
    pop()

    beginShape()
    for (let i = 0; i < 100; i++) {
      const angle = i/99 * TWO_PI
      let x = 100 * cos(angle)
      let y = 150 * sin(angle)
      const dx = -50 + 100 * noise(x*0.005, y*0.005, frameCount*0.03)
      const dy = -50 + 100 * noise(x*0.005, y*0.005, frameCount*0.03 + 12345)
      x += dx
      y += dy
      vertex(x, y)
    }

    beginContour()
    for (let i = 0; i < 100; i++) {
      var angle = -i/99 * TWO_PI
      var x = 50 * cos(angle)
      var y = 70 * sin(angle)
      var dx = -50 + 100 * noise(x*0.005, y*0.005, frameCount*0.03)
      var dy = -50 + 100 * noise(x*0.005, y*0.005, frameCount*0.03 + 12345)
      x += dx
      y += dy
      vertex(x, y)
    }
    endContour()

    endShape()
  } else if (scene === 1) {
    background('#7f97f0')

    push()
    beginClip()
    scale(0.8)
    rotateX(frameCount * 0.02);
    rotateY(frameCount * 0.02);
    torus(200, 100);
    endClip()

    textAlign(LEFT, TOP)
    textSize(25)
    let txt = ''
    for (let i = 0; i < 5; i++) {
      txt += 'beginClip() / endClip() / '
    }
    for (let y = -300; y < 300; y += 25) {
      text(txt, -300 + (((300 + y)/25) % 2) * -100, y)
    }

    pop()
  } else if (scene === 2) {
    background('#69947f')

    push()
    textSize(80)
    textAlign(CENTER, CENTER)
    text('filter(BLUR)', 0, 0)

    const progress = (t / 3000) % 1

    filter(BLUR, map(pow(constrain((progress - 0.25) * 2, 0, 1), 2), 0, 1, 0, 100))
    pop()
  } else if (scene === 3) {
    background('#f7a56a')

    push()
    translate(250, 250)
    textAlign(RIGHT, BOTTOM)
    textSize(50)
    text('buildGeometry()', 0, 0)
    pop()

    push()
    rotateX(PI * -0.1);

    noStroke();
    specularMaterial(100)
    shininess(100)
    lights();

    // Draw a bunch of bugs
    for (let i = 0; i < 80; i++) {
      push();
      // Move each bug to a random position and rotation using noise
      translate(
        map(noise(frameCount*0.001+123.456*i, i, 0), 0, 1, -500, 500),
        0,
        map(noise(frameCount*0.001+123.456*i, i, 100), 0, 1, -700, 600)
      );
      rotateY(noise(frameCount*0.01, i, 200) * TWO_PI);
      scale(0.1);
      model(bug);
      pop();
    }
    pop()
  } else if (scene === 4) {
    background('#f5427e')

    push()
    textAlign(CENTER, CENTER)
    textSize(50)
    text('p5*js 1.8.0', 0, 0)
    pop()
  }
}
